#!/usr/bin/env bash
#
# Apply the deployment identity to Flutter's generated Android host project.
#
# `apps/client/android/` is generated by `flutter create` and is not committed,
# so the application id and launcher label are recreated on every clean checkout
# (Flutter's default `com.example.<pubspec name>`). Editing them by hand works
# only until the next regeneration, so every build path calls this script.
#
# It must run after `flutter create --platforms=android .` and before any
# `flutter build apk`. Values can be overridden per deployment; the defaults are
# the ones the repository ships.
#
# Environment:
#   STRICT_ANDROID_APP_ID     application id      (default com.strictproxy.client)
#   STRICT_ANDROID_APP_LABEL  launcher label      (default StrictProxy)
#
set -euo pipefail

CLIENT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ANDROID_DIR="${CLIENT_DIR}/android"
APP_ID="${STRICT_ANDROID_APP_ID:-com.strictproxy.client}"
APP_LABEL="${STRICT_ANDROID_APP_LABEL:-StrictProxy}"

fail() {
  printf 'error: %s\n' "$1" >&2
  exit 1
}

[[ -d "${ANDROID_DIR}/app" ]] \
  || fail "no generated Android project at ${ANDROID_DIR} — run 'flutter create --platforms=android .' first"

if [[ ! "$APP_ID" =~ ^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)+$ ]]; then
  fail "STRICT_ANDROID_APP_ID is not a valid Android application id: ${APP_ID}"
fi
if [[ ! "$APP_LABEL" =~ ^[A-Za-z0-9._-]+$ ]]; then
  fail "STRICT_ANDROID_APP_LABEL must be a single word of letters, digits, '.', '_' or '-': ${APP_LABEL}"
fi

GRADLE="${ANDROID_DIR}/app/build.gradle.kts"
[[ -f "$GRADLE" ]] || GRADLE="${ANDROID_DIR}/app/build.gradle"
[[ -f "$GRADLE" ]] || fail "neither build.gradle.kts nor build.gradle exists under ${ANDROID_DIR}/app"

MANIFEST="${ANDROID_DIR}/app/src/main/AndroidManifest.xml"
[[ -f "$MANIFEST" ]] || fail "missing AndroidManifest.xml at ${MANIFEST}"

# Flutter writes the id twice (namespace for code/R, applicationId for the
# installed package). Both must move together or the launcher activity stops
# resolving after installation.
OLD_ID="$(sed -n 's/^[[:space:]]*applicationId[[:space:]]*[= ][[:space:]]*"\([^"]*\)".*/\1/p' "$GRADLE" | head -1)"
[[ -n "$OLD_ID" ]] || fail "could not read applicationId from ${GRADLE}"

if [[ "$OLD_ID" != "$APP_ID" ]]; then
  escaped_old="$(printf '%s' "$OLD_ID" | sed 's/\./\\./g')"
  sed -i.bak -E \
    -e "s/(namespace[[:space:]]*[= ][[:space:]]*\")${escaped_old}(\")/\1${APP_ID}\2/" \
    -e "s/(applicationId[[:space:]]*[= ][[:space:]]*\")${escaped_old}(\")/\1${APP_ID}\2/" \
    "$GRADLE"
  rm -f "${GRADLE}.bak"

  # Move the Kotlin/Java sources so the declared package still matches its path.
  for language in kotlin java; do
    old_src="${ANDROID_DIR}/app/src/main/${language}/${OLD_ID//./\/}"
    new_src="${ANDROID_DIR}/app/src/main/${language}/${APP_ID//./\/}"
    [[ -d "$old_src" ]] || continue
    mkdir -p "$(dirname "$new_src")"
    mv "$old_src" "$new_src"
    find "$new_src" -type f \( -name '*.kt' -o -name '*.java' \) -print0 \
      | xargs -0 -r sed -i.bak -E "s/^package[[:space:]]+.*$/package ${APP_ID}/"
    find "$new_src" -type f -name '*.bak' -delete
    rmdir -p "$(dirname "$old_src")" 2>/dev/null || true
  done
  echo "Android application id: ${OLD_ID} -> ${APP_ID}"
else
  echo "Android application id: ${APP_ID} (already set)"
fi

sed -i.bak -E "s/(android:label=\")[^\"]*(\")/\1${APP_LABEL}\2/" "$MANIFEST"
rm -f "${MANIFEST}.bak"

# Fail here rather than shipping an APK with a placeholder identity: a wrong
# package id cannot be fixed after the first install or Play Store upload.
grep -q "applicationId[[:space:]]*[= ][[:space:]]*\"${APP_ID}\"" "$GRADLE" \
  || fail "applicationId did not land in ${GRADLE}"
grep -q "namespace[[:space:]]*[= ][[:space:]]*\"${APP_ID}\"" "$GRADLE" \
  || fail "namespace did not land in ${GRADLE}"
grep -q "android:label=\"${APP_LABEL}\"" "$MANIFEST" \
  || fail "launcher label did not land in ${MANIFEST}"
if grep -q 'com\.example' "$GRADLE" "$MANIFEST"; then
  fail "placeholder identity still present in the generated Android project"
fi

echo "Android launcher label: ${APP_LABEL}"
